            receipt("a", "A", "D", "2026-04-01T04:00:00-08:00"),
        ]

        self.assertEqual(
            run({"command": "summary", "protocol": "2", "receipts": receipts}),
            {"protocol": "2", "accepted_count": 1, "duplicate_count": 1},
        )
        self.assertEqual(select_receipts(receipts, "2"), {"a"})

